// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2017, "2-3", [{"author":"Л. Фёдорова","question":"Встретились в лесу два зверя.\n— Привет, косолапый! — сказал один.\n— Здорово, косой! — ответил второй.\nЧто за звери встретились?","choices":["волк и медведь","волк и заяц","медведь и волк","ёжик и заяц","заяц и медведь."],"key":"Д","review":["Приветствие в лесу","Косолапым в сказках зовут медведя. Первый зверь говорит «Привет, косолапый!», значит, именно второй зверь — медведь.","Он отвечает «Здорово, косой!». Косым называют зайца, значит, первым заговорил заяц, а ответил медведь."]},{"author":"Б. Иомдин","question":"Вот начало известного стихотворения Корнея Чуковского:\nУ меня зазвонил телефон.\n— Кто говорит?\n— Слон.\n— Откуда?\n— От верблюда.\n— Что вам надо?\n— Шоколада.\n— Для кого?\n— Для сына моего.\nА для кого нужен шоколад?","choices":["для слона","для слонёнка","для верблюда","для верблюжонка","для Чуковского."],"key":"Б","review":["Шоколад из стихотворения","Проследи, кто говорит по телефону. За шоколадом обратился слон, а верблюд назван в ответе на вопрос «Откуда?»","Слон просит шоколад для своего сына. Детёныш слона — слонёнок, ему и нужно угощение."]},{"author":"Л. Фёдорова","question":"Что может вырасти на дереве и на лбу?","choices":["ветка","гриб","цветок","шишка","ягода."],"key":"Г","review":["На дереве и на лбу","Вспомни, что растёт на деревьях. На сосне можно увидеть шишки, а на разных деревьях бывают ветки, цветы и ягоды.","Если удариться лбом, на нём может появиться припухлость. Её тоже зовут шишкой, поэтому одно слово отвечает на оба вопроса."]},{"author":"Л. Фёдорова","question":"Какое из имён нельзя перенести на следующую строку?","choices":["<em>Марья</em>","<em>Юлия</em>","<em>Анна</em>","<em>Софья</em>","все эти имена можно переносить."],"key":"Б","review":["Как перенести имя","Проверь, можно ли оставить с обеих сторон переноса больше одной буквы. Подходят «Ма-рья», «Ан-на» и «Со-фья».","У имени «Юлия» возможные места между слогами дают «Ю-лия» или «Юли-я». Оба раза остаётся одна буква, поэтому имя перенести нельзя."]},{"author":"Е. Муравенко","question":"В стихотворении Александра Шибаева о буквах есть такие строчки:\nЧтобы «…» не укатилась —\nКрепко к столбику прибью.\nОй, смотри-ка, что случилось:\nПолучилась буква «…».\nКакие буквы надо поставить вместо пропусков?","choices":["Ь и Ы","Г и П","О и Ю","З и В","Ш и Щ."],"key":"В","review":["Буква у столбика","Подумай, какая буква может покатиться. Круглая «О» похожа на кольцо, а в стихотворении её держит столбик.","Нарисуй вертикальную черту и соедини её короткой чертой с буквой «О» справа. Вместе получатся знакомые очертания «Ю»."]},{"author":"Л. Фёдорова","question":"Миша пишет сочинение «Утро в деревне»: <em>На рассвете нас всегда будит</em> <em>звонкое ...</em> .","choices":["<em>кар-кар</em>","<em>ку-ку</em>","<em>кря-кря</em>","<em>кукареку</em>","<em>ква-ква</em>."],"key":"Г","review":["Рассвет в деревне","Узнай голоса животных. «Кар-кар» кричит ворона, «ку-ку» — кукушка, «кря-кря» — утка, «ква-ква» — лягушка.","По деревенскому двору на рассвете раздаётся петушиное «кукареку». Оно и будит героев Мишиного сочинения."]},{"author":"И. Рубанов","question":"Мама оставила сыну записку: «Петя, пойди в магазин и купи буханку ...». К сожалению, край записки с последним словом Петя случайно оторвал. Но он всё равно понял, что мама попросила его купить … .","choices":["масла","сыра","хлеба","конфет","кваса."],"key":"В","review":["Оторванная записка","Прочитай слово перед оторванным краем. «Буханка» — целое изделие из теста, которое испекли в форме или на противне.","Собери привычные сочетания. Говорят «кусок сыра», «пачка масла», «пакет конфет», «бутылка кваса», а вот буханка бывает хлеба."]},{"author":"Л. Фёдорова","question":"Когда девочки ходили в детский сад, их там называли Даша, Таня, Валя, Оля, Нина, а когда они пошли записываться в первый класс, их попросили назвать полные имена. Какое из имён осталось без изменений?","choices":["Даша","Таня","Валя","Оля","Нина."],"key":"Д","review":["Имена к первому классу","Вспомни, как зовут девочек полностью. Даша — Дарья, Таня — Татьяна, Валя — Валентина, Оля — Ольга.","«Нина» уже полное имя. Поэтому девочке достаточно назвать себя так же, как её называли в детском саду."]},{"author":"Б. Иомдин","question":"<em>Даша у нас настоящая ...</em> . Как вряд ли закончат фразу?","choices":["<em>бегунья</em>","<em>врунья</em>","<em>лгунья</em>","<em>глазунья</em>","<em>колдунья.</em>"],"key":"Г","review":["Какая у нас Даша","Посмотри, кого называют словами из списка. Бегунья бегает, врунья и лгунья обманывают, а колдунья умеет колдовать.","Глазунья — это яичница, у которой желтки остались целыми. Дашу в обычном разговоре таким словом вряд ли назовут."]},{"author":"Л. Фёдорова","question":"Свежий хлеб бывает мягким, а несвежий обычно называют … .","choices":["твёрдым","жёстким","прочным","плотным","чёрствым."],"key":"Д","review":["Как называют несвежий хлеб","Слово «несвежий» говорит о том, что хлеб полежал и подсох. Слова «твёрдый», «жёсткий», «прочный» и «плотный» описывают свойства разных предметов.","Для залежавшегося хлеба есть привычное слово «чёрствый». Сравни «мягкая свежая булка» и «чёрствая булка»."]},{"author":"С. Переверзева","question":"На пляже Серёжа нарисовал на песке картинку и подписал её название. Набежавшая волна смыла первые буквы, и получилось «ЛЕНЬКИЙ ЦВЕТОЧЕК».\n― Аленький? ― спросила мама.\n― Нет, ― ответил Серёжа. ― Другого цвета.\nА какого?","choices":["зелёного","голубого","жёлтого","белого","красного."],"key":"Г","review":["Цветок на песке","Сохрани все буквы от слова «ЛЕНЬКИЙ». Мамино «аленький» действительно подходит по буквам, но Серёжа сказал, что цвет другой.","Припиши в начале «бе». Получится «беленький», то есть белый. Остальные предложенные цвета такой подписи не дают."]},{"author":"Е. Муравенко","question":"В каком из предложений слово <em>взять</em> имеет совсем не то значение, что в остальных?","choices":["<em>Дядя Цезарь позвал на охоту пса Пифа и взял его ошейник</em> <em>с поводком</em>.","<em>Дядя Цезарь взял с собой ружьё</em>.","<em>Пиф попросил дядю Цезаря взять рюкзак с едой</em>.","<em>В лесу дядя Цезарь велел Пифу взять след зайца</em>.","<em>Заяц взял веточку и пощекотал Пифу нос</em>."],"key":"Г","review":["Пиф и слово «взять»","Найди предметы, которые можно унести в лапах или руках. В предложениях берут ошейник, ружьё, рюкзак и веточку.","«Взять след» означает уловить запах и начать идти по нему. Сам след Пифу уносить не нужно, поэтому здесь «взять» имеет другой смысл."]},{"author":"Е. Муравенко","question":"Котёнку Финдусу, большому выдумщику и озорнику, посвящена целая серия книг. Одна из книжек называется «Поделки Финдуса». Художник на обложке этой книги вставил в слово <em>поделки</em> ещё одну букву и зачеркнул её. Что это за буква?","choices":["<em>д</em>","<em>о</em>","<em>р</em>","<em>л</em>","<em>ъ</em>."],"key":"В","review":["Буква на обложке","Сравни два слова о Финдусе. Он мастерит поделки и затевает проделки. Художник мог показать оба его занятия в одном названии.","Вставь «р» после «п» в слово «поделки». Получится «Проделки Финдуса». Если зачеркнуть добавленную букву, снова видно название «Поделки Финдуса»."]},{"author":"Е. Муравенко","question":"Во всех словах прочерками заменены буквы <em>а</em> или <em>о</em>. В четырёх словах на месте прочерков должны быть одинаковые буквы, а в одном — разные. В каком?","choices":["<em>к_рм_н</em>","<em>м_р_з</em>","<em>_г_нь</em>","<em>г_р_ж</em>","<em>ф_н_рь</em>."],"key":"Д","review":["Две буквы в пропусках","Запиши «карман», «мороз», «огонь» и «гараж». В «кармане» и «гараже» в пропусках стоят два «а», а в «морозе» и «огне» — два «о».","Осталось слово «фонарь». В первой части пишется «о», во второй «а», поэтому в этом варианте буквы разные."]},{"author":"Л. Фёдорова","question":"Острым не бывает … .","choices":["нос","перец","карандаш","нож","ёж."],"key":"Д","review":["Что бывает острым","Проверь разные значения слова «острый». У носа и карандаша бывает заострённый кончик, у ножа — острое лезвие, а у перца — жгучий вкус.","У ежа острые иголки. Самого зверька за эти иголки называют колючим, поэтому «острый ёж» в обычной речи не подходит."]},{"author":"С. Сай","question":"Какое слово не связано с другими по смыслу?","choices":["<em>смешать</em>","<em>смешат</em>","<em>смесь</em>","<em>мешали</em>","<em>смешался</em>."],"key":"Б","review":["Слова о смешивании","Свяжи слова с действием. Можно смешать краски, получить смесь, сказать «краски смешались» или «их мешали ложкой».","Форма «смеша́т» отвечает на вопрос «что делают?» от глагола «смешить». Например, «шутки смешат детей», то есть заставляют смеяться."]},{"author":"Е. Бикмаев","question":"Очень много слов русского языка оканчивается на … .","choices":["-<em>летний</em>","-<em>зимний</em>","-<em>весенний</em>","-<em>осенний</em>","среди ответов (А)–(Г) нет правильного."],"key":"А","review":["Чем кончаются слова","Сравни «зимний», «весенний», «осенний» и «летний». Первые три обычно называют связь с определённым сезоном.","В «двухлетний», «трёхлетний» и «десятилетний» та же часть «-летний» говорит о числе лет. Числа можно менять, поэтому таких слов очень много."]},{"author":"О. Подлесская","question":"Читаем потешку для малышей:\nНа крайчике, на сарайчике\nДве вороны сидят, обе врозь глядят:\nИз-за дохлого жука перессорились!\nКуда смотрят вороны?","choices":["вниз","вверх","в разные стороны","в одну сторону","друг на друга."],"key":"В","review":["Вороны на сарайчике","Объясни слово «врозь» с помощью противоположного слова «вместе». Вороны поссорились и больше не глядят вместе в одну сторону.","Об одной птице можно сказать, что она отвернулась влево, о другой — вправо. Значит, они смотрят в разные стороны."]},{"author":"С. Переверзева","question":"В русском пересказе сказочной повести шведского писателя Ингемара Фьелля действие происходит в городке Елсо. А каких деревьев в нём растёт больше всего?","choices":["берёз и тополей","клёнов и ясеней","сосен и елей","дубов и лип","каштанов и рябин."],"key":"В","review":["Название городка Елсо","Рассмотри русское название «Елсо». В его начале можно узнать сокращённое слово «ель», а в конце — начало слова «сосна».","Соедини «ел-» и «со-», чтобы проверить догадку. Название складывается именно из частей названий елей и сосен."]},{"author":"Е. Муравенко","question":"Какое слово реже всех остальных употребляется перед сочетанием <em>из головы</em>?","choices":["<em>выскочить</em>","<em>выбежать</em>","<em>вылететь</em>","<em>выкинуть</em>","<em>выбросить.</em>"],"key":"Б","review":["Что уходит из головы","Составь знакомые выражения. Забытая мысль может «вылететь из головы» или «выскочить из головы». Ненужную мысль можно «выкинуть» или «выбросить из головы».","«Выбежать» обычно говорят о том, кто вышел бегом, например «выбежал из комнаты». Сочетание «выбежать из головы» встречается гораздо реже."]},{"author":"Л. Фёдорова","question":"В четырёх случаях, рассказывая о сказочном персонаже, мы можем убрать одно слово в его имени. В одном случае обычно так не делают. В каком?","choices":["<em>Красная Шапочка</em>","<em>Серый волк</em>","<em>Золотой гусь</em>","<em>Снежная королева</em>","<em>Железный Дровосек</em>."],"key":"А","review":["Короткие имена героев","Попробуй оставить только название героя. В сказке можно продолжать рассказывать про Волка, Гуся, Королеву и Дровосека, если уже ясно, о ком речь.","Имя «Красная Шапочка» целиком обозначает девочку. Если оставить только «Шапочка», слово прежде всего обозначит её головной убор, поэтому в обычном пересказе имя сохраняют целиком."]},{"author":"А. Леонтьева","question":"Стихотворение Михаила Яснова «Я учу котёнка» заканчивается так:\n…Мой котёнок так старается:\n______ учит\nИ мяучит.\nКакое слово мы пропустили?","choices":["<em>буквы</em>","<em>звуки</em>","<em>цифры</em>","<em>имя</em>","<em>слово</em>."],"key":"Г","review":["Чему учится котёнок","Прочитай две последние строки подряд. Автор играет со звуками, поэтому начало строки «И мяучит» подсказывает, какие звуки надо услышать перед «учит».","Подставь «имя». Сочетания «имя учит» и «и мяучит» звучат похоже, а по смыслу котёнка действительно можно учить откликаться на имя."]},{"author":"Е. Бикмаев","question":"Вставьте пропущенное слово в загадку.\nХодит по двору ______,\nРазгребает лапкой сор,\nРасправляет с шумом крылья\nИ садится на забор.","choices":["<em>петух</em>","<em>журавль</em>","<em>драчун</em>","<em>будильник</em>","<em>светильник</em>."],"key":"Г","review":["Кто ходит по двору","Определи, кого описывают лапки, крылья и двор. По этим приметам угадывается петух. Посмотри, как его можно назвать, не выдавая отгадку сразу.","Петух по утрам будит людей своим криком. Поэтому в загадке его можно назвать «будильником», как вещь, которая помогает проснуться."]},{"author":"И. Иткин","question":"В польском языке есть слово wieko, которое произносится как [в’э́ко]. Что оно означает?","choices":["человек","окно","веник","ветка","крышка."],"key":"Д","review":["Польское слово «wieko»","Произнеси данное польское слово. «В’э́ко» похоже на русское «веко», то есть подвижную часть кожи над глазом.","Веко прикрывает глаз, как крышка прикрывает коробку. Поэтому среди данных переводов подходит «крышка»."]},{"author":"Е. Муравенко","question":"Яша набрал на компьютере слова <em>лото</em>, <em>пот</em>, <em>труд</em>, <em>тир</em>, <em>тара</em>, а шутник Саша заменил в них все буквы <em>т</em> одной и той же другой буквой. Как ни удивительно, после этого программа проверки орфографии подчеркнула как неверное лишь одно слово. Какое Яшино слово превратилось в неверное?","choices":["<em>лото</em>","<em>пот</em>","<em>труд</em>","<em>тир</em>","<em>тара</em>."],"key":"А","review":["Одинаковая замена букв","Подбери букву по сочетанию «_руд». Буква «п» даёт «пруд», а та же замена в «по_», «_ир» и «_ара» даёт «поп», «пир» и «пара».","В «лото» буква «т» тоже заменяется на «п», и выходит «лопо». Это единственное из получившихся сочетаний, которое программа отметит."]},{"author":"Е. Бикмаев","question":"Произнесём слово <em>уж</em>. Если мы добавим к нему звук [д] в начале, то услышим слово <em>душ</em>. В какой ещё паре второе слово можно получить из первого, добавив в начале или в конце слова один звук и не изменяя остальных?","choices":["<em>кров — кровь</em>","<em>зуб — зубр</em>","<em>рог — урок</em>","<em>сень — осень</em>","<em>слив — слива</em>."],"key":"В","review":["Один добавленный звук","Проверяй произношение. В конце слова «рог» слышится [к], поэтому к звучанию [рок] можно добавить [у] и получить [урок].","В «кровь» меняется твёрдость последнего согласного, а в «зубр» и «слива» слышатся [б] и [в] вместо [п] и [ф]. В «осень» безударная «е» звучит иначе, чем ударная «е» в «сень». Значит, подходит только пара «рог — урок»."]},{"author":"Е. Муравенко","question":"В книжке-головоломке Антона Тилипмана «Зубака» во многих словах перепутались буквы. Вот, например, была <em>азбука</em> — стала <em>зубака</em>. Если вы правильно расставите буквы в «словах» <em>артмышка</em>, <em>бульог</em>, <em>гуляшка</em>, <em>дикокрол</em>, <em>огронос</em>, получится пять названий живых существ. Сколько среди них птиц?","choices":["ни одной","одна","две","три","четыре."],"key":"Б","review":["Живые существа из букв","Переставь буквы. Из «артмышка» получится «мартышка», из «бульог» — «голубь», из «гуляшка» — «лягушка», из «дикокрол» — «крокодил», из «огронос» — «носорог».","Мартышка и носорог — млекопитающие, лягушка — земноводное, крокодил — пресмыкающееся. Птица среди них только одна, голубь."]},{"author":"Б. Иомдин","question":"Вот несколько болгарских слов и их переводы на русский язык: вълк — <em>волк</em>, конче — <em>жеребёнок</em>, патка — <em>утка</em>, петел — <em>петух</em>, прасе — <em>поросёнок</em>, пиле — <em>цыплёнок</em>. Как по-болгарски будет «Русский медвежонок»?","choices":["Руски медвежонок","Руско мече","Руски мечок","Руски мишка","Руска мишка."],"key":"Б","review":["Болгарские имена зверят","Посмотри на переводы названий детёнышей. Болгарские «конче», «прасе» и «пиле» оканчиваются на «е».","Такую же форму имеет «мече», то есть «медвежонок». В болгарском это слово среднего рода, поэтому из вариантов к нему подходит «Руско мече»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
